const getUserGMRawScore = `-- name: GetUserGMRawScore :one
SELECT COALESCE(SUM(
    CASE m.difficulty
        WHEN 'easy' THEN 2
        WHEN 'medium' THEN 4
        WHEN 'hard' THEN 6
        WHEN 'nightmare' THEN 8
        ELSE 4
    END
    + LEAST((SELECT COUNT(DISTINCT a.user_id) FROM mystery_attempts a WHERE a.mystery_id = m.id), 5)
), 0)::bigint AS score
FROM mysteries m
WHERE m.user_id = $1 AND m.solved = TRUE
`

