const sumProfileResponseVotes = `-- name: SumProfileResponseVotes :one
SELECT COALESCE(SUM(rv.value), 0)::bigint AS total
FROM response_votes rv
JOIN responses r ON rv.response_id = r.id
WHERE r.user_id = $1
`

func (q *Queries) SumProfileResponseVotes(ctx context.Context, userID uuid.UUID) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumProfileResponseVotes, userID)
	var total int64
	err := row.Scan(&total)
	return total, err
}

const sumProfileTheoryVotes = `-- name: SumProfileTheoryVotes :one
SELECT COALESCE(SUM(tv.value), 0)::bigint AS total
FROM theory_votes tv
JOIN theories t ON tv.theory_id = t.id
WHERE t.user_id = $1
`

func (q *Queries) SumProfileTheoryVotes(ctx context.Context, userID uuid.UUID) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumProfileTheoryVotes, userID)
	var total int64
	err := row.Scan(&total)
	return total, err
}

