const userEmailInUse = `-- name: UserEmailInUse :one
SELECT EXISTS(SELECT 1 FROM users u WHERE LOWER(u.email) = LOWER($1) AND u.email <> '' AND u.id <> $2) AS in_use
`

type UserEmailInUseParams struct {
	Lower string
	ID    uuid.UUID
}

func (q *Queries) UserEmailInUse(ctx context.Context, arg UserEmailInUseParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, userEmailInUse, arg.Lower, arg.ID)
	var in_use bool
	err := row.Scan(&in_use)
	return in_use, err
}

const userRequiresEmailVerification = `-- name: UserRequiresEmailVerification :one
SELECT (NOT u.email_verified AND NOW() >= u.verify_grace_until)::boolean AS blocked
FROM users u
WHERE u.id = $1
`

func (q *Queries) UserRequiresEmailVerification(ctx context.Context, id uuid.UUID) (bool, error) {
	row := q.db.QueryRowContext(ctx, userRequiresEmailVerification, id)
	var blocked bool
	err := row.Scan(&blocked)
	return blocked, err
}
